create or replace function public.ui_provider_outcomes(p_provider_id uuid,p_limit integer default 500) returns table(provider_id uuid,survey_code text,survey_name text,metric_code text,metric_name text,metric_category text,unit text,source_cohort_code text,audience text,collection_year_from smallint,collection_year_to smallint,metric_value numeric,response_count integer,confidence_low numeric,confidence_high numeric,national_benchmark numeric,source_label text,source_url text,collection_version integer,evidence_hash text,evidence_storage_path text,source_institution_key text,source_study_area_code text,source_metric_code text,observed_at timestamptz,status text,metadata jsonb) language sql stable security definer set search_path to 'public','catalogue','ref','pipeline','auth' as $function$ select po.provider_id,os.code,os.name,om.code,om.name,om.category,om.unit,po.source_cohort_code,po.audience,po.collection_year_from,po.collection_year_to,po.metric_value,po.response_count,po.confidence_low,po.confidence_high,po.national_benchmark,ps.label,ps.url,nullif(ps.metadata->>'collection_version','')::integer,ea.content_hash,ea.storage_path,po.source_institution_key,po.source_study_area_code,po.source_metric_code,po.observed_at,po.status,po.metadata from catalogue.provider_outcomes po join ref.outcome_surveys os on os.id=po.survey_id join ref.outcome_metrics om on om.id=po.metric_id join pipeline.sources ps on ps.id=po.source_id left join pipeline.evidence_artifacts ea on ea.id=po.evidence_id where po.provider_id=p_provider_id and os.source_family='QILT' and auth.uid() is not null order by po.collection_year_to desc,os.code,po.source_cohort_code,om.category,om.code limit least(greatest(coalesce(p_limit,500),1),1000); $function$; revoke all on function public.ui_provider_outcomes(uuid,integer) from public,anon; grant execute on function public.ui_provider_outcomes(uuid,integer) to authenticated,service_role;
